export const tenantModules = pgTable(
  'tenant_modules',
  {
    tenantId: uuid('tenant_id').notNull(),
    moduleKey: text('module_key').notNull(),
    enabled: boolean().default(false).notNull(),
    level: text().default('').notNull(),
    config: jsonb().default({}).notNull(),
    changedBy: uuid('changed_by'),
    changedAt: timestamp('changed_at', { withTimezone: true, mode: 'string' })
      .defaultNow()
      .notNull()
  },
  (table) => [
    uniqueIndex('tenant_modules_one_crm_level')
      .using('btree', table.tenantId.asc().nullsLast().op('uuid_ops'))
      .where(sql`((module_key = 'crm'::text) AND enabled)`),
    foreignKey({
      columns: [table.tenantId],
      foreignColumns: [tenants.id],
      name: 'tenant_modules_tenant_id_fkey'
    }).onDelete('restrict'),
    foreignKey({
      columns: [table.moduleKey],
      foreignColumns: [moduleCatalog.moduleKey],
      name: 'tenant_modules_module_key_fkey'
    }),
    foreignKey({
      columns: [table.changedBy],
      foreignColumns: [users.id],
      name: 'tenant_modules_changed_by_fkey'
    }).onDelete('set null'),
    primaryKey({ columns: [table.tenantId, table.moduleKey], name: 'tenant_modules_pkey' }),
    check(
      'tenant_modules_level_check',
      sql`level = ANY (ARRAY[''::text, 'lite'::text, 'full'::text])`
    ),
    check('tenant_modules_check', sql`(module_key = 'crm'::text) = (level <> ''::text)`),
    check('tenant_modules_check1', sql`(module_key <> 'platform'::text) OR enabled`)
  ]
);

export const metricsDaily = pgTable(
  'metrics_daily',
  {
    tenantId: uuid('tenant_id').notNull(),
    day: date().notNull(),
    leads: integer().default(0).notNull(),
    calls: integer().default(0).notNull(),
    contactsReached: integer('contacts_reached').default(0).notNull(),
    estimatesBooked: integer('estimates_booked').default(0).notNull(),
    // You can use { mode: "bigint" } if numbers are exceeding js number limitations
    bookedValueCents: bigint('booked_value_cents', { mode: 'number' }).default(0).notNull(),
    // You can use { mode: "bigint" } if numbers are exceeding js number limitations
    wonRevenueCents: bigint('won_revenue_cents', { mode: 'number' }).default(0).notNull(),
    avgSpeedToLeadS: numeric('avg_speed_to_lead_s', { precision: 10, scale: 2 }),
    speedToLeadSamples: integer('speed_to_lead_samples').default(0).notNull(),
    computedAt: timestamp('computed_at', { withTimezone: true, mode: 'string' })
      .defaultNow()
      .notNull()
  },
  (table) => [
    foreignKey({
      columns: [table.tenantId],
      foreignColumns: [tenants.id],
      name: 'metrics_daily_tenant_id_fkey'
    }).onDelete('restrict'),
    primaryKey({ columns: [table.tenantId, table.day], name: 'metrics_daily_pkey' }),
    check('metrics_daily_leads_check', sql`leads >= 0`),
    check('metrics_daily_calls_check', sql`calls >= 0`),
    check('metrics_daily_contacts_reached_check', sql`contacts_reached >= 0`),
    check('metrics_daily_estimates_booked_check', sql`estimates_booked >= 0`)
  ]
);
